import{_ as e,c as t,o as p,ah as n}from"./chunks/framework.BxT5r71R.js";const M=JSON.parse('{"title":"出道1年，MAZZEL逐渐建立起“自我肯定感”与“自尊心”","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART3/11_出道1年，MAZZEL逐渐建立起“自我肯定感”与“自尊心”.md","filePath":"zh-cn/Management2/PART3/11_出道1年，MAZZEL逐渐建立起“自我肯定感”与“自尊心”.md"}'),r={name:"zh-cn/Management2/PART3/11_出道1年，MAZZEL逐渐建立起“自我肯定感”与“自尊心”.md"};function _(o,a,Z,i,l,s){return p(),t("div",null,[...a[0]||(a[0]=[n('<p>► 2024年7月</p><h2 id="出道1年-mazzel逐渐建立起-自我肯定感-与-自尊心" tabindex="-1">出道1年，MAZZEL逐渐建立起“自我肯定感”与“自尊心” <a class="header-anchor" href="#出道1年-mazzel逐渐建立起-自我肯定感-与-自尊心" aria-label="Permalink to &quot;出道1年，MAZZEL逐渐建立起“自我肯定感”与“自尊心”&quot;">​</a></h2><p>#领导力 #成长 #制作 #自我肯定感 #MAZZEL</p><h3 id="如果每个人没有建立起一定程度的自我肯定感与自尊心-也很难真正肯定身边的人。" tabindex="-1">“如果每个人没有建立起一定程度的自我肯定感与自尊心，也很难真正肯定身边的人。” <a class="header-anchor" href="#如果每个人没有建立起一定程度的自我肯定感与自尊心-也很难真正肯定身边的人。" aria-label="Permalink to &quot;“如果每个人没有建立起一定程度的自我肯定感与自尊心，也很难真正肯定身边的人。”&quot;">​</a></h3><p><strong>MAZZEL出道1周年。2024年6月、7月，他们举办首次全国巡演MAZZEL 1st One Man Tour 2024 “Join us in the PARADE”，走过八座城市，完成九场演出，并宣布将于10月在体育馆举行追加演出。经历首次巡演后大幅成长，是新人组合常见的成长轨迹。不过，在巡演最后一站东京场上，他们展现出的变化似乎不止于技巧和舞台表现。他们对自身表演的自信，以及享受现场的样子，都令人印象深刻。他们引以为长的“个性”，也似乎变得更加鲜明。SKY-HI如何看待如今的他们？</strong></p><p>我一直很希望，第一次巡演结束时，组合内部能像现在这样，形成关系融洽的氛围。如今真的做到了，我很高兴。大家渐渐有了“朝着同一个目标一起努力吧”的共识。</p><p>这是他们自己一点点培养起来的。而在这个过程中，我首先要做的，就是为他们的自信和安心感提供保障。</p><p>当然，也可以埋头努力，试着借此摆脱不自信和不安。但以我的经验来看，我觉得想靠努力克服这些情绪，往往并不奏效。他们本来就越来越需要审视自己的内心，精神状态也容易起伏。</p><p>审视内心固然是必要的过程，但对于他们这样的组合，与其一味往这个方向深入，不如先增强每个人的自我肯定感和自尊心。如果这些没有达到一定程度，就很难真正肯定同组成员等身边的人，组合的整体氛围也就好不起来。所以我一直认为，要肯定他人，首先得有一个可以肯定自己的环境。我想，现在他们已经走到这一步了。</p><h3 id="成员之间的爆发力开始相互传递" tabindex="-1">成员之间的爆发力开始相互传递 <a class="header-anchor" href="#成员之间的爆发力开始相互传递" aria-label="Permalink to &quot;成员之间的爆发力开始相互传递&quot;">​</a></h3><p>出道后的大约半年里，工作人员与他们之间确实存在一些沟通问题。MAZZEL的成员总想着“不这样做会挨批评”“不能这样做”，表演时常常放不开。偶尔有人突破拘谨，其他人却没有跟上，最后也就停留在“今天他很放得开呢”。但现在，只要有人展现出爆发力，就会带动大家；有人往前冲，其他人也会自然地接应。有时，他们展现自我的方式连我们都没想到（笑），但我反而觉得这样特别好。</p><p>真希望大家都能看看RYUKI在巡演首场福冈演出中的那段MC。那是我至今笑得最开怀的一次，观众大概也一边笑，一边感动吧。通常，这种时候大家多半会表达感谢，或者说“最喜欢大家了”之类的话……啊，我真想把细节都想起来。大意是这样：RYUKI一开始也说，“我真的特别喜欢大家，也特别喜欢我们现在这样的关系”，接着却说，“要是有人敢小瞧你们，我就替你们出头！”差不多是这样（笑）。</p><p>后来他越来越兴奋，一口气说个不停，成员们一边笑，一边拦着他（笑）。周围的人嘴上说着“喂，喂（笑）”，却也觉得RYUKI这样的个性很有趣，而且尊重他的个性。早期还看不到这样的场面，所以我当时一边大笑，一边特别高兴。这只是一个例子。最近，我常常感受到成员们自然流露的个性，尤其是RYUKI和SEITO。</p><p>我觉得，本来就没有毫无个性的人。每个人都有个性的种子，只要顺着自己的心意去做，个性就会充分展现出来。而MAZZEL的成员背景各不相同，差异还很大，所以我不禁期待：如果所有人都能自然流露出原本的个性，究竟会是什么样子？再往后会发展成什么样，甚至连我也想象不出来（笑）。如今看他们演出时，越来越多的瞬间已经显露出这样的苗头。</p><p>出道这一年，有顺利的时候，也有不顺利的时候，今后应该也会如此反复。真正重要的是，身边有伙伴，可以一起分享喜悦，也一起分担不如意。当然，我也会一直陪在他们身边。但即便如此，同伴之间的关系依然重要，毕竟不是每个人都能拥有这样的伙伴。对MAZZEL来说，如今的伙伴关系是一笔宝贵的财富，也为今后的发展增添了一份安心。</p><p>回顾出道以来的历程，我觉得这次巡演的首场和最后一场，都是他们的重要转折点。接下来，他们应该会有很大的进步，希望大家多多期待。</p><h3 id="激发全员展现自我的队长" tabindex="-1">激发全员展现自我的队长 <a class="header-anchor" href="#激发全员展现自我的队长" aria-label="Permalink to &quot;激发全员展现自我的队长&quot;">​</a></h3><p><strong>谈到团队关系，今年3月1日，也就是出道半年多后，MAZZEL通过YouTube上的一段纪录影像，宣布成员TAKUTO出任队长。影像中，SKY-HI分析了MAZZEL当时的状况：“大家顾及彼此，能提出改善现场的意见，却不太容易提出突破现状的想法。”他还表示：“如果有一位现场队长，加快彼此之间的传球速度，就能突破一层束缚。”我们再次请他谈了谈设立队长的意义，以及此后发生的变化。</strong></p><p>一个团队里，大家太顾虑彼此，有时就会互相观望，谁也不先行动。不过，对MAZZEL来说，所有人都按自己的想法展现自我，组合一定会更有趣。话虽如此，即使大家都尽情展现自己，我也不太能想象Takkun（TAKUTO的昵称）跟着起哄的样子（笑）。但有他可以依靠，其他人就能觉得“尽情去做也没关系！”我认为，大家需要这样的底气。</p><p>如今公司规模扩大，旗下艺人也增加了。和BE:FIRST刚起步时不同，无论哪位艺人，我都越来越难参与他们的所有现场工作了。你看，矫正牙齿时，如果连续好几天不戴矫治器，牙齿不是很快就会往原来的位置移吗？道理是一样的，我希望有人能在现场持续贯彻我的想法。从这个意义上说，Takkun或许就是保持器（牙齿矫正后用于维持矫治效果的装置）。</p><p>他的情绪不会今天一个样、明天一个样。只要跟他说“我们上次是这么说的吧”，他就能立刻回想起来，进入相应的状态。我觉得，这正是MAZZEL的现场所需要的角色。Takkun也有不少俏皮的一面，但他也有超出实际年龄的成熟之处（采访时为25岁），也有坚定的意志。如果有机会主动展现这些特质，对他本人应该也是一件好事。</p><p>我曾经想过，在《MISSION》这类体现MAZZEL态度的歌曲之前，如果由Takkun以队长身份说一段MC，应该会展现出不一样的魅力。虽然首次巡演实际把这段MC安排在了《MISSION》之后，但能看到Takkun新的一面，还是很好的。他头脑灵活，直觉也敏锐，所以我想，到了明年，大家或许会看到一个出乎意料的Takkun。</p><h3 id="今后要进一步突出-独特性" tabindex="-1">今后要进一步突出“独特性” <a class="header-anchor" href="#今后要进一步突出-独特性" aria-label="Permalink to &quot;今后要进一步突出“独特性”&quot;">​</a></h3><p>本次巡演将在PIA ARENA MM和大阪城音乐厅各追加两场演出，共计四场。首次巡演的门票确实一票难求，但对于出道才1年的组合来说，四场体育馆演出的规模仍然相当可观。另一方面，有时又会觉得，他们“还没有进入大众视野”。</p><p>应该有很多人没能买到票吧。购票需求之高，普通组合在出道第一年几乎不可能达到。事实上，目前BMSG旗下粉丝俱乐部会员人数增长率最高的，就是MAZZEL。现在的他们确实有一种魅力：不管通过什么渠道，只要看到过他们一次，就会想支持他们。我想，这大概也是会员人数增长的原因。</p><p>先从较小的场地起步，能够真切感受到观众席上每一个人，再逐步扩大规模，这和BE:FIRST当时的思路一样。不过，今后通过选秀企划No No Girls出道的女子组合，情况会有所不同；至于第三个组合，成员已经有舞台经验，我想又得换一个角度考虑。只是，首次巡演该做多少包装、保留多少未经修饰的本色，这个平衡很难把握，筹备过程中确实有些地方需要谨慎拿捏。</p><p>至于有人说他们“还没有进入大众视野”，其实我觉得，太在意这个也没什么用。真要这么说，哪个组合都一样，我至今也会对BE:FIRST有这样的想法。只要还在做艺人，这就是永恒的课题，也是需要持续努力的目标。即使不断登上音乐节目，扩大影响的空间也终究有限，唯有一次次把握登场的机会。相比之下，首先应该珍惜眼前的成果：他们已经有了这样的势头和成绩，粉丝也确实在不断增加，这本身就值得高兴和感激。</p><p>不过，对MAZZEL，我确实想更进一步，突出他们的独特性。下一张单曲里，我已经有一些想做的事了。</p><p>对他们来说，我觉得，一旦再也看不到那份独特、与众不同之处，才是真正的危机。不过，我实在无法想象那一天会到来。</p>',29)])])}const h=e(r,[["render",_]]);export{M as __pageData,h as default};
